<div class="management-grid"><section class="panel table-wrap"><h2>News categories</h2><table><thead><tr><th>Name</th><th>Order</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($items as $row): ?><tr><td><?= e($row['name_en']) ?><small><?= e($row['name_si']) ?> / <?= e($row['name_ta']) ?></small></td><td><?= (int)$row['order_index'] ?></td><td><?= e($row['status']) ?></td><td><a href="?edit=<?= (int)$row['id'] ?>">Edit</a><?php if ($user['role']==='super_admin'): ?> · <form action="<?= e(url('admin/categories/delete/'.$row['id'])) ?>" method="post" data-confirm="Delete this category? Only empty categories can be deleted." style="display:inline"><?= csrf() ?><button class="link-button" style="color:#b91c1c">Delete</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></section><form method="post" class="panel form-stack"><?= csrf() ?><input type="hidden" name="id" value="<?= (int)($edit['id'] ?? 0) ?>"><h2><?= $edit ? 'Edit category' : 'Add a category' ?></h2><?php foreach (['en'=>'English name','si'=>'Sinhala name','ta'=>'Tamil name'] as $l=>$label) $field('name_'.$l,$label,'text',null,'required maxlength="255"'); $field('slug','Category address'); $field('order_index','Order','number',$edit['order_index'] ?? 0); ?><label class="check"><input type="checkbox" name="active" <?= ($edit['status'] ?? 'active')==='active' ? 'checked' : '' ?>> Active in navigation</label><button class="button">Save category</button><a href="<?= e(url('admin/categories')) ?>">Clear form</a></form></div>
